solution.solution.cpp:
#include <vector>

long long fib(int n)
{
    static std::vector<long long> known{ 0, 1 };
    if (n < static_cast<int>(known.size()))
    {
        return known[static_cast<std::size_t>(n)];
    }
    const long long value{ fib(n - 1) + fib(n - 2) };
    known.push_back(value);
    return value;
}

unitTests:
TEST("the first few") { CHECK_EQ(fib(0), 0); CHECK_EQ(fib(1), 1); CHECK_EQ(fib(2), 1); CHECK_EQ(fib(10), 55); }
TEST("fast enough for big inputs") { CHECK_EQ(fib(50), 12586269025LL); CHECK_EQ(fib(90), 2880067194370816120LL); }
TEST("asking again gives the same answer") { CHECK_EQ(fib(30), 832040); CHECK_EQ(fib(30), 832040); }

